  /* Reporte un chemin (M/m, C/c, L/l, Z/z) par la matrice [a, b, c, d, e, f] ; sortie en absolu. */
  function mapPath(d, m) {
    const tok = d.match(/[MmCcLlZz]|-?(?:\d+\.?\d*|\.\d+)/g) || [];
    const f = (v) => Math.round(v * 10) / 10;
    const P = (X, Y) => f(m[0] * X + m[2] * Y + m[4]) + ' ' + f(m[1] * X + m[3] * Y + m[5]);
    const out = [];
    let i = 0, cmd = '', x = 0, y = 0, x0 = 0, y0 = 0;
    const n = () => +tok[i++];
    while (i < tok.length) {
      const t = tok[i];
      if (/[A-Za-z]/.test(t)) {
        cmd = t;
        i++;
        if (cmd === 'z' || cmd === 'Z') { out.push('Z'); x = x0; y = y0; }
        continue;
      }
      const rel = cmd === cmd.toLowerCase();
      const bx = rel ? x : 0, by = rel ? y : 0;
      if (cmd === 'M' || cmd === 'm') {
        x = bx + n(); y = by + n(); x0 = x; y0 = y;
        out.push('M' + P(x, y));
        cmd = rel ? 'l' : 'L';
      } else if (cmd === 'L' || cmd === 'l') {
        x = bx + n(); y = by + n();
        out.push('L' + P(x, y));
      } else if (cmd === 'C' || cmd === 'c') {
        const v = [n(), n(), n(), n(), n(), n()];
        out.push('C' + P(bx + v[0], by + v[1]) + ' ' + P(bx + v[2], by + v[3]) + ' ' + P(bx + v[4], by + v[5]));
        x = bx + v[4]; y = by + v[5];
      } else {
        i++;
      }
    }
    return out.join('');
  }

